def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue

                # Start only at the beginning of a diagonal run.
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                run = [(r, c)]
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc

                if len(run) < 2:
                    continue

                # Runs that already touch the edge are part of the given motif,
                # rather than lines to extend.
                if any(x == 0 or x == h - 1 or y == 0 or y == w - 1
                       for x, y in run):
                    continue

                # Extend from both ends through background cells.
                for sr, sc, step_r, step_c in (
                    (run[0][0] - dr, run[0][1] - dc, -dr, -dc),
                    (run[-1][0] + dr, run[-1][1] + dc, dr, dc),
                ):
                    rr, cc = sr, sc
                    while (0 <= rr < h and 0 <= cc < w
                           and grid[rr][cc] == bg):
                        out[rr][cc] = color
                        rr += step_r
                        cc += step_c

    return out
